css:
.d-rn{position:relative;width:300px;max-width:100%;height:150px;padding-top:4px;font-family:var(--sans)}
.d-rn-text{width:158px;margin:0;font-size:11px;line-height:1.75;color:var(--muted)}
.d-rn-text b{font-weight:650;color:var(--ink)}
.d-rn-note{position:absolute;top:10px;right:2px;width:114px;padding:7px 9px 8px;border:1px solid var(--ink);border-radius:2px;background:var(--paper);transform:rotate(-1.5deg);box-shadow:0 1px 0 var(--line)}
.d-rn-tab{display:block;height:1px;margin-bottom:6px;background:#e8c34a}
.d-rn-btn{width:100%;padding:2px 0;border:0;border-bottom:1px solid var(--line);background:transparent;font-family:var(--mono);font-size:9px;letter-spacing:.06em;color:var(--ink);text-align:left;cursor:pointer}
.d-rn-btn:focus-visible{outline:1px solid var(--ink);outline-offset:1px}
.d-rn-more{max-height:0;overflow:hidden;transition:max-height 280ms cubic-bezier(.2,.75,.25,1)}
.d-rn-ctx{margin:0;padding-top:5px;font-size:9px;line-height:1.6;color:var(--muted)}
.d-rn.is-open .d-rn-more{max-height:58px}

init:
root => {
  const box = root.querySelector('.d-rn');
  if (!box || box.dataset.rn) return;
  box.dataset.rn = '1';
  const btn = box.querySelector('.d-rn-btn');
  const toggle = () => {
    const open = !box.classList.contains('is-open');
    box.classList.toggle('is-open', open);
    btn.setAttribute('aria-expanded', String(open));
    btn.textContent = open ? '旁注 03 · 收起' : '旁注 03 · 展开';
  };
  btn.addEventListener('click', toggle);
}
